function calendarStats(){const s=weekSummary(db.events,db.history,db.workouts,week),n=Object.values(s).reduce((a,x)=>a+x.actualMinutes,0),p=Object.values(s).reduce((a,x)=>a+x.plannedMinutes,0),u=Object.values(s).reduce((a,x)=>a+x.unknownDuration,0);return '<section class="week-stats"><div class="row between"><strong>Weekoverzicht</strong><small>'+h(dateLabel(week,{day:"numeric",month:"short"}))+" – "+h(dateLabel(dateAdd(week,6),{day:"numeric",month:"short"}))+'</small></div><div class="week-stats-grid">'+Object.entries(types).map(([k,label])=>{const t=s[k]||{planned:0,completed:0};return '<div class="'+k+'"><i></i><small>'+h(k==="football"?"Training":k==="match"?"Wedstrijd":k==="other"?"Overig":label)+'</small><strong>'+(t.planned+t.completed)+'</strong></div>'}).join("")+'</div><div class="row between"><small>Gedaan · '+n+' min</small><small>Nog gepland · '+p+' min'+(u?" + "+u+" zonder duur":"")+'</small></div></section>'}
