function eventCard(e){const done=db.history.find(x=>x.eventId===e.id),title=e.type==="fitness"?(workout(e.workoutId)?.name||"Workout"):e.name;return '<div class="card event '+h(e.type)+' inside" style="margin-bottom:9px">'+b('<div class="row between"><div><small>'+h(types[e.type])+(e.time?" · "+h(e.time):"")+'</small><h3>'+h(title)+'</h3><small>'+(done?"✓ "+done.minutes+" min":e.minutes?e.minutes+" min gepland":"Gepland")+'</small></div><span>›</span></div>',done?"history-open":"event-open","link",'data-id="'+(done?done.id:e.id)+'"')+(!done?b("Verplaatsen","event-move","quiet",'data-id="'+e.id+'"'):"")+'</div>'}
