function builder(){return header("Training bewerken","schemas")+'<form id="builder-form" data-form="builder" class="stack">'+field("Naam training","name",draft.name,"text","required maxlength=100")+draft.exercises.map((e,i)=>'<section class="card builder-card" data-order="'+i+'"><div class="head row between"><span>Oefening '+(i+1)+'/'+draft.exercises.length+'</span><span class="row">'+b("⠿","drag-handle","drag-handle",'data-i="'+i+'" aria-label="Versleep oefening"')+b("↑","exercise-up","quiet",'data-i="'+i+'" aria-label="Omhoog"')+b("↓","exercise-down","quiet",'data-i="'+i+'" aria-label="Omlaag"')+b("×","exercise-remove","quiet danger",'data-i="'+i+'" aria-label="Verwijderen"')+'</span></div><div class="inside stack"><h2>'+h(e.name)+'</h2><div class="formrow"><div>'+field("Sets","sets"+i,e.sets,"number","required min=1 max=30")+'</div><div>'+field("Reps","reps"+i,e.reps,"text","required")+'</div><div>'+(!e.bodyweight?field("Gewicht","kg"+i,e.kg,"number","min=0 max=2000 step=any"):"")+'</div></div><label class="checklabel"><input name="ea'+i+'" type="checkbox" '+(e.ea?"checked":"")+'> Each (ea)</label><label class="checklabel"><input name="bw'+i+'" data-bodyweight type="checkbox" '+(e.bodyweight?"checked":"")+'> Bodyweight (geen kg)</label>'+field("Rusttijd","rest"+i,e.rest,"number","required min=0 max=900")+advancedBuilder(e,i)+(e.equipment==="Dumbbell"?'<small>Gewicht per dumbbell</small>':"")+'</div></section>').join("")+b("+ Oefening toevoegen","library-pick","outline full")+'<button class="primary" type="submit">Training opslaan</button></form>'}
