function tick(){const el=$("timer");if(!el||!db.active)return;const left=Math.max(0,Math.ceil(((db.active.restUntil||0)-Date.now())/1000)),elapsed=Math.max(0,Math.floor((Date.now()-db.active.started)/1000));el.textContent=Math.floor(left/60)+":"+String(left%60).padStart(2,"0");$("elapsed").textContent=Math.floor(elapsed/60)+":"+String(elapsed%60).padStart(2,"0");$("rest-dock").hidden=left===0}
function startTraining(){if(opened?.eventId&&db.history.some(x=>x.eventId===opened.eventId)){alert("Deze training is al afgerond.");return}if(db.active){go("training");return}const ev=opened.eventId?event(opened.eventId):null,w=ev?eventTemplate(ev):workout(opened.workoutId);if(!w||!w.exercises.length)return;db.active={id:id(),type:"fitness",eventId:ev?.id||null,workoutId:w.id,name:w.name,date:dateToday(),started:Date.now(),restUntil:0,exercises:snapshot(w)};save();go("training")}
