function loadPanel(){const l=sportLoad(db.history,loadWeek,dateAdd(loadWeek,6)),max=Math.max(1,...l.days.map(d=>d.minutes)),current=db.recovery.find(x=>x.date===dateToday());return '<section class="card inside load-panel"><div class="row between"><h2>Sportbelasting</h2><div class="row">'+b("‹","load-week","quiet",'data-n="-1" aria-label="Vorige week"')+b("›","load-week","quiet",'data-n="1" aria-label="Volgende week"')+'</div></div><small>'+fmt(loadWeek)+' – '+fmt(dateAdd(loadWeek,6))+'</small><div class="metric-grid"><div><small>Sporttijd</small><strong>'+amount(l.minutes)+' <small>min</small></strong></div><div><small>Belasting (min × RPE)</small><strong>'+(l.rated?amount(l.load):"—")+'</strong><small>'+l.rated+' / '+l.minutes+' min met RPE</small></div></div><div class="load-chart" aria-label="Sporttijd per dag">'+l.days.map(d=>'<div><div class="load-column">'+Object.entries(d.types).map(([k,m])=>'<span class="'+h(k)+'" style="height:'+Math.max(1,m/max*76)+'px" title="'+h(types[k])+' '+m+' min"></span>').join("")+'</div><small>'+["Zo","Ma","Di","Wo","Do","Vr","Za"][weekday(d.date)]+'</small><small>'+d.minutes+'</small></div>').join("")+'</div><div class="load-legend">'+Object.entries(types).map(([k,v])=>'<small class="'+k+'"><i></i>'+h(v)+'</small>').join("")+'</div></section>'+card("Herstel vandaag",current?'<div class="metric-grid recovery-metrics">'+[["Slaap",current.sleep],["Energie",current.energy],["Spierpijn",current.soreness]].map(([k,v])=>'<div><small>'+k+'</small><strong>'+v+'/5</strong></div>').join("")+'</div>'+b("Check-in bewerken","recovery","quiet full"):b("Dagelijkse check-in","recovery","outline full"))}
function progress(){const ids=[...new Set(db.history.filter(x=>x.type==="fitness").flatMap(x=>x.exercises.map(e=>e.exerciseId)))];return header("Progressie")+loadPanel()+b("Trainingshistorie","nav","outline full",'data-page="history"')+'<h1 class="sectiontitle">Persoonlijke records</h1>'+ids.map(eid=>{const variants=exerciseMetrics(db.history,eid);if(!variants.length)return "";const v=variants[0];return card(v.name,b('<div class="row between"><span>'+h(v.bodyweight?amount(v.maxReps)+" reps":amount(v.maxWeight)+" kg")+(variants.length>1?' · '+variants.length+' varianten':'')+'</span><span>›</span></div>',"progress-open","link",'data-id="'+h(eid)+'"'))}).join("")}
function exerciseProgress(){const all=exerciseMetrics(db.history,selectedExercise),name=all[0]?.name||allLibrary().find(x=>x.id===selectedExercise)?.name||"Oefening",variant=all.find(v=>v.key===progressVariant)||all[0];if(!variant)return header(name,"progress")+'<p class="empty">Nog geen voltooide werksets.</p>';const from=progressMonths?monthShift(dateToday(),-progressMonths):"",v=exerciseMetrics(db.history,selectedExercise,from,dateToday()).find(x=>x.key===variant.key),metric=variant.bodyweight?"reps":progressMetric,key={weight:"maxWeight",reps:"maxReps",e1rm:"e1rm",volume:"volume"}[metric],unit=metric==="reps"?"reps":"kg",rows=(v?.rows||[]).filter(x=>x[key]!==null),max=Math.max(1,...rows.map(x=>x[key])),points=rows.map((x,i)=>[28+(rows.length===1?132:i*268/(rows.length-1)),111-x[key]/max*86]);return header(name,"progress")+'<p class="muted">'+h(variant.bodyweight?"Bodyweight":variant.equipment||"Gewicht")+(variant.ea?" · each":"")+'</p>'+(all.length>1?'<div class="chip-row">'+all.map(x=>b(h((x.bodyweight?"Bodyweight":x.equipment||"Gewicht")+(x.ea?" · ea":"")),"progress-variant",x.key===variant.key?"chip on":"chip",'data-id="'+h(x.key)+'"')).join("")+'</div>':"")+'<div class="chip-row">'+[1,3,6,12,0].map(m=>b(m?m+"M":"Alles","progress-period",m===progressMonths?"chip on":"chip",'data-n="'+m+'"')).join("")+'</div><div class="metric-grid">'+(variant.bodyweight?[["Record reps",variant.maxReps,"reps"],["Werksetsessies",v?.rows.length||0,""]]:[["Record gewicht",variant.maxWeight,"kg"],["Geschatte 1RM",variant.e1rm,"kg"],["Volume periode",v?.volume||0,"kg"]]).map(([k,n,u])=>'<div><small>'+k+'</small><strong>'+amount(n)+' <small>'+u+'</small></strong></div>').join("")+'</div><section class="card inside"><div class="chip-row">'+(variant.bodyweight?[["reps","Reps"]]:[["weight","Gewicht"],["e1rm","1RM"],["volume","Volume"],["reps","Reps"]]).map(([k,l])=>b(l,"progress-metric",metric===k?"chip on":"chip",'data-id="'+k+'"')).join("")+'</div>'+(rows.length?'<svg class="chart" viewBox="0 0 320 138" role="img" aria-label="Progressie '+unit+'"><path d="M28 111 H300 M28 25 V111" stroke="#667080" fill="none"/><text x="1" y="25">'+amount(max)+'</text><text x="1" y="112">0</text><polyline points="'+points.map(p=>p.join(",")).join(" ")+'" fill="none" stroke="#ff8900" stroke-width="2"/>'+points.map(p=>'<circle cx="'+p[0]+'" cy="'+p[1]+'" r="3" fill="#ff8900"/>').join("")+'<text x="28" y="132">'+h(rows[0].date.slice(5))+'</text><text x="300" y="132" text-anchor="end">'+h(rows.at(-1).date.slice(5))+'</text></svg>':'<p class="empty">Geen waarden in deze periode.</p>')+'<p class="form-hint">Werksets; warming-up uitgesloten. 1RM is een schatting (1–10 reps). Volume = kg × reps, ×2 bij each of dumbbell, niet dubbel.</p></section>'+rows.slice().reverse().map(r=>card(fmt(r.date),b(amount(r[key])+" "+unit+" ›","history-open","link",'data-id="'+h(r.id)+'"'))).join("")}

const APP_VERSION="0.7.0";
let updateRegistration=null,updateMessage="Nog niet gecontroleerd",updateBusy=false,updateApplying=false,updateSeenController=null;
function updateBlocked(){return !booted||!!db.active||!!storageError||!!queue?.status.failure||$("dialog").open||page!=="settings"}
function updatePanel(){
 const waiting=!!updateRegistration?.waiting,active=!!db.active;
 return '<div class="row between"><small>Geïnstalleerde versie</small><strong id="installed-version">'+APP_VERSION+'</strong></div><div class="line"><p id="update-message" class="muted" role="status">'+h(waiting?(active?"Update beschikbaar · rond je training eerst af.":updateApplying?updateMessage:!["Nog niet gecontroleerd","Controleren…","Geen nieuwe update gevonden.","Update beschikbaar.","Update wordt gedownload…"].includes(updateMessage)?updateMessage:"Update beschikbaar. Je lokale gegevens blijven behouden."):updateMessage)+'</p>'+b(updateBusy?"Controleren…":"Controleren op updates","update-check","quiet full",updateBusy||updateApplying?"disabled":"")+(waiting?b("Bijwerken","update-apply","primary",updateBlocked()||updateApplying?"disabled":""):"")+'</div>';
}
function refreshUpdatePanel(){const el=$("update-panel");if(el)el.innerHTML=updatePanel()}
function observeUpdate(reg){
 updateRegistration=reg;
 const watch=worker=>{if(!worker)return;worker.addEventListener("statechange",()=>{if(worker.state==="redundant"&&!reg.waiting){updateMessage="Update kon niet worden geïnstalleerd. Probeer opnieuw."}refreshUpdatePanel()})};
 watch(reg.installing);
 reg.addEventListener("updatefound",()=>{watch(reg.installing);refreshUpdatePanel()});
 refreshUpdatePanel();
}
async function checkUpdate(manual=false){
 if(updateBusy||updateApplying)return;
 if(navigator.onLine===false){if(manual){updateMessage="Geen internetverbinding. Probeer online opnieuw.";refreshUpdatePanel()}return}
 if(!updateRegistration){if(manual){updateMessage="Updatefunctie nog niet beschikbaar. Open de app opnieuw.";refreshUpdatePanel()}return}
 updateBusy=true;if(manual)updateMessage="Controleren…";refreshUpdatePanel();
 try{await updateRegistration.update();const worker=updateRegistration.installing;if(worker){await new Promise(resolve=>{if(["installed","activated","redundant"].includes(worker.state)){resolve();return}const timer=setTimeout(resolve,12000);worker.addEventListener("statechange",()=>{if(["installed","activated","redundant"].includes(worker.state)){clearTimeout(timer);resolve()}})})}updateMessage=updateRegistration.waiting?"Update beschikbaar.":worker?.state==="redundant"?"Update kon niet worden geïnstalleerd. Probeer opnieuw.":updateRegistration.installing?"Update wordt gedownload…": "Geen nieuwe update gevonden."}
 catch{updateMessage="Updatecontrole mislukt. Probeer opnieuw met internetverbinding."}
 finally{updateBusy=false;refreshUpdatePanel()}
}
function requestActivation(worker){
 return new Promise((resolve,reject)=>{const channel=new MessageChannel();const timer=setTimeout(()=>{channel.port1.close();reject(Error("Geen bevestiging ontvangen. Sluit andere appvensters en probeer opnieuw."))},10000);channel.port1.onmessage=e=>{clearTimeout(timer);channel.port1.close();e.data?.ok?resolve():reject(Error(e.data?.reason||"Bijwerken niet mogelijk"))};try{worker.postMessage({type:"FM_ACTIVATE"},[channel.port2])}catch(e){clearTimeout(timer);channel.port1.close();reject(e)}});
}
async function applyUpdate(){
 if(updateApplying||updateBlocked()||!updateRegistration?.waiting)return;
 updateApplying=true;for(const id of ["app","nav","accessory","dialog"])$(id).inert=true;
 updateMessage="Lokale wijzigingen opslaan…";refreshUpdatePanel();
 try{
  await queue.flush();
  if(updateBlocked()||queue.status.pending)throw Error("Rond de training af en controleer de lokale opslag.");
  const worker=updateRegistration.waiting;if(!worker)throw Error("Update niet meer beschikbaar. Controleer opnieuw.");
  updateMessage="Bijwerken…";refreshUpdatePanel();
  await requestActivation(worker);
  // controllerchange will reload only this explicitly frozen, saved client.
  setTimeout(()=>{if(updateApplying){updateApplying=false;for(const id of ["app","nav","accessory","dialog"])$(id).inert=!!(storageError||queue?.status.failure);updateMessage="Update nog niet actief. Sluit andere appvensters en probeer opnieuw.";refreshUpdatePanel()}},15000);
 }catch(e){updateApplying=false;for(const id of ["app","nav","accessory","dialog"])$(id).inert=!!(storageError||queue?.status.failure);updateMessage=e.message;refreshUpdatePanel()}
}
async function initUpdates(){
 if(!("serviceWorker" in navigator))return;
 updateSeenController=navigator.serviceWorker.controller;
 navigator.serviceWorker.addEventListener("controllerchange",()=>{
  const current=navigator.serviceWorker.controller;
  if(updateApplying&&current&&current!==updateSeenController){location.reload();return}
  if(updateSeenController&&current!==updateSeenController){updateMessage="Appversie gewijzigd. Sluit de app na opslaan en open opnieuw.";refreshUpdatePanel()}
  updateSeenController=current;
 });
 try{const reg=await navigator.serviceWorker.register("./sw.js",{updateViaCache:"none"});observeUpdate(reg);if(navigator.onLine!==false)checkUpdate()}
 catch{updateMessage="Offline updatefunctie niet beschikbaar.";refreshUpdatePanel()}
}

function settings(){return header("Instellingen")+card("Applicatie",'<div id="update-panel">'+updatePanel()+'</div>')+card("Account",'<p>Lokale testversie. Apple-login en cloudsynchronisatie zijn uitgesteld.</p>')+card("Gegevens",'<p id="storage-detail">Opgeslagen op dit apparaat (IndexedDB)</p>'+b("Exporteer lokale gegevens","export","outline full")+b("Vraag blijvende browseropslag aan","persist-storage","quiet full")+'<p class="muted">Gebruik fictieve testgegevens. Browseropslag kan gewist worden, bijvoorbeeld bij verwijderen van websitegegevens. Exporteer regelmatig een back-up. Er worden geen trainingsgegevens naar Supabase verzonden.</p>')+card("Toekomstige integraties","Apple-login · Cloudsynchronisatie · BridgeAthletic-import · Apple Health · AI")}
function showDialog(title,body,handler){let d=$("dialog");d.setAttribute("aria-labelledby","dialog-title");d.innerHTML='<form id="dialog-form" class="compact-form"><div class="dialog-heading"><h2 id="dialog-title">'+h(title)+'</h2>'+b("×","dialog-close","dialog-x",'aria-label="Sluiten"')+'</div><div class="dialog-fields">'+body+'</div><div class="dialog-actions">'+b("Annuleren","dialog-close","dialog-cancel")+'<button type="submit" class="primary">Bevestigen</button></div></form>';if(!d.open)d.showModal();$("dialog-form").onsubmit=ev=>{ev.preventDefault();const form=new FormData(ev.currentTarget);d.close();handler(form)}}
function activityNew(){showDialog("Nieuwe activiteit",selectField("Type","type",'<option value="football">Voetbaltraining</option><option value="match">Voetbalwedstrijd</option><option value="other">Overige sport</option>')+field("Naam (optioneel)","name","","text",'placeholder="Bijv. teamtraining" maxlength=100')+fieldPair(field("Datum","date",selected,"date","required"),field("Tijdstip (optioneel)","time","","time"))+fieldPair(field("Verwachte duur","minutes","90","number","required min=1 max=1440"),field("Herhalen","weeks","1","number","required min=1 max=52"))+'<div class="repeat-days" hidden>'+weekdayPicker()+'</div><p class="form-hint">1 week = eenmalige activiteit.</p>',f=>{const date=f.get("date"),weeks=Number(f.get("weeks")),days=f.getAll("days").map(Number),type=f.get("type"),dates=weeks===1?[{date}]:occurrences(date,weeks,days.length?days:[weekday(date)]),series=id();dates.forEach(d=>db.events.push({id:id(),series,type,name:String(f.get("name")).trim()||types[type],date:d.date,time:f.get("time"),minutes:Number(f.get("minutes"))}));selected=date;week=monday(selected);save();go("today")});const form=$("dialog-form"),update=()=>{const repeating=Number(form.elements.weeks.value)>1;form.querySelector(".repeat-days").hidden=!repeating;for(const input of form.querySelectorAll('[name="days"]'))input.disabled=!repeating;form.querySelector(".form-hint").textContent=repeating?"Kies weekdagen; zonder selectie geldt de startdag.":"1 week = eenmalige activiteit."};form.elements.weeks.addEventListener("input",update);update()}
function workoutOptions(){return db.workouts.map(w=>'<option value="'+w.id+'">'+h(w.name)+'</option>').join("")}
function planWorkout(){if(!db.workouts.length){newDraft();return}showDialog("Fitnessworkout plannen",selectField("Workout","workoutId",workoutOptions())+fieldPair(field("Datum","date",selected,"date","required"),field("Tijdstip","time","","time"))+field("Verwachte duur (minuten)","minutes","","number","min=1 max=1440"),f=>{db.events.push({id:id(),type:"fitness",workoutId:f.get("workoutId"),date:f.get("date"),time:f.get("time"),minutes:f.get("minutes")?Number(f.get("minutes")):0});selected=f.get("date");week=monday(selected);save();go("today")})}
function openEvent(e){if(!e)return;if(e.type==="fitness"){opened={eventId:e.id,workoutId:e.workoutId};go("preview");return}showDialog(e.name,'<p class="form-hint">Gepland · '+fmt(e.date)+'</p>'+fieldPair(field("Datum","date",e.date,"date","required"),field("Werkelijke duur","minutes",e.minutes,"number","required min=1 max=1440"))+rpeField(),f=>{if(db.history.some(x=>x.eventId===e.id))return;db.history.push({id:id(),eventId:e.id,type:e.type,name:e.name,date:f.get("date"),minutes:Number(f.get("minutes")),rpe:validRpe(f.get("rpe"))?Number(f.get("rpe")):null,finished:Date.now()});selected=f.get("date");week=monday(selected);save();go("today")})}
function newProgram(){if(!db.workouts.length){alert("Maak eerst een workout aan.");newDraft();return}showDialog("Nieuw programma",field("Naam","name","","text","required maxlength=100")+fieldPair(field("Startdatum","start",dateToday(),"date","required"),field("Duur","weeks","6","number","required min=1 max=52")),f=>{let p={id:id(),name:String(f.get("name")).trim(),start:f.get("start"),weeks:Number(f.get("weeks")),entries:[],overrides:{}};if(!p.name)return;db.programs.push(p);save();opened=p.id;go("programView");addProgramWorkout()})}
function addProgramWorkout(){const p=program(opened);if(!p)return;showDialog("Workout toevoegen",selectField("Workout","workoutId",workoutOptions())+weekdayPicker(),f=>{const days=f.getAll("days").map(Number),wid=f.get("workoutId");if(!days.length||!workout(wid)){alert("Kies een workout en minimaal één weekdag.");return}if(p.entries.some(x=>x.workoutId===wid)){alert("Deze workout is al opgenomen in dit programma.");return}p.entries.push({workoutId:wid,days});occurrences(p.start,p.weeks,days).forEach(o=>db.events.push({id:id(),type:"fitness",programId:p.id,workoutId:wid,...o}));save();render()})}
function weekTargets(wid){let p=program(opened),w=workout(wid);if(!p||!w)return;const ov=p.overrides[wid]||{};showDialog("Richtwaarden per week",Array.from({length:p.weeks},(_,i)=>'<div class="row between"><h3>Week '+(i+1)+'</h3>'+(i<p.weeks-1?b("Kopieer naar volgende","week-copy","quiet",'data-i="'+i+'" data-count="'+w.exercises.length+'"'):"")+'</div>'+w.exercises.map((e,j)=>'<small>'+h(e.name)+'</small><div class="row"><div class="grow">'+field("Reps","r"+i+"_"+j,ov[i+1]?.[e.id]?.reps??e.reps,"text","required")+'</div>'+(!e.bodyweight?'<div class="grow">'+field("Gewicht","k"+i+"_"+j,ov[i+1]?.[e.id]?.kg??e.kg,"number","min=0 max=2000 step=any")+'</div>':"")+'</div>').join("")).join(""),f=>{let next={};for(let i=0;i<p.weeks;i++){next[i+1]={};for(let j=0;j<w.exercises.length;j++){let e=w.exercises[j],reps=f.get("r"+i+"_"+j),kg=f.get("k"+i+"_"+j)??"";if(!repRange(reps)||(!e.bodyweight&&kg!==""&&!validKg(kg))){alert("Ongeldige richtwaarden.");return}next[i+1][e.id]={reps,kg}}}p.overrides[wid]=next;save();render()})}
function historyEdit(){const x=db.history.find(s=>s.id===detailId);if(!x)return;showDialog("Prestatie bewerken",field("Datum","date",x.date,"date","required")+field("Duur (minuten)","minutes",x.minutes,"number","required min=1 max=1440")+rpeField(x.rpe??"")+(x.exercises||[]).map((e,i)=>'<h3>'+h(e.name)+'</h3>'+e.logs.map((s,j)=>s.done?'<div class="row"><div class="grow">'+field("Set "+(j+1)+" reps","r"+i+"_"+j,s.reps,"number","required min=1 max=999")+'</div>'+(!e.bodyweight?'<div class="grow">'+field("Gewicht","k"+i+"_"+j,s.kg,"number","required min=0 max=2000 step=any")+'</div>':"")+'</div>':"").join("")).join(""),f=>{const next=copy(x);next.date=f.get("date");next.minutes=Number(f.get("minutes"));next.rpe=validRpe(f.get("rpe"))?Number(f.get("rpe")):null;for(let i=0;i<(next.exercises||[]).length;i++){let e=next.exercises[i];for(let j=0;j<e.logs.length;j++){let s=e.logs[j];if(!s.done)continue;let reps=f.get("r"+i+"_"+j),kg=f.get("k"+i+"_"+j);if(!validReps(reps)||(!e.bodyweight&&!validKg(kg))){alert("Ongeldige invoer.");return}s.reps=reps;s.kg=e.bodyweight?"":kg}}db.history[db.history.indexOf(x)]=next;save();render()})}
document.addEventListener("keydown",ev=>{if(page==="training"&&ev.key==="Enter"&&ev.target.dataset.field){ev.preventDefault();focusNext()}});
document.addEventListener("submit",ev=>{if(ev.target.dataset.form!=="builder")return;ev.preventDefault();syncBuilder();if(!draft.name.trim()||!draft.exercises.length||!validSupersets(draft.exercises)||draft.exercises.some(e=>!repRange(e.reps)||!Number.isInteger(e.warmupCount)||e.warmupCount<0||e.warmupCount>10||(e.warmupCount>0&&(!repRange(e.warmupReps)||(e.warmupKg!==""&&!validKg(e.warmupKg))))||!Number.isInteger(e.sets)||e.sets<1||e.sets>30||!Number.isInteger(e.rest)||e.rest<0||e.rest>900||(!e.bodyweight&&e.kg!==""&&!validKg(e.kg)))){alert("Controleer naam, sets, reps, gewicht en supersets (twee opeenvolgende oefeningen met evenveel werksets).");return}const idx=db.workouts.findIndex(w=>w.id===draft.id);if(idx<0)db.workouts.push(copy(draft));else db.workouts[idx]=copy(draft);opened={workoutId:draft.id};save();draft=null;go("preview")});
document.addEventListener("input",ev=>{const t=ev.target;if(page==="training"&&t.dataset.field){let s=db.active.exercises[Number(t.dataset.ex)].logs[Number(t.dataset.set)];s[t.dataset.field]=t.value.replace(",",".");save();updateAccessory()}if(page==="libraryView"&&t.id==="search"){filters.q=t.value;updateFilters()}});
